 "private/edit_by_label": {
  "scope": "private",
  "tags": [
   "Trading",
   "Matching Engine",
   "Private"
  ],
  "summary": "Modifies an order identified by its label.",
  "description": "Modifies an order identified by its label. This method works only when there is exactly one open order with the specified label. You can change the order's price, amount, and/or other properties such as time-in-force, post-only, reduce-only, trigger conditions, or advanced order type. Changes take effect immediately. **Note:** For spot orders routed to Coinbase Exchange, fills come back asynchronously. It is recommended to receive fills from the `user.trades` channel. **📖 Related Articles:** - [Order Management Best Practices](https://docs.deribit.com/articles/order-management-best-practices) - [Spot Trading: Deribit and Coinbase-Routed Instruments](https://docs.deribit.com/articles/spot-trading-venues) **Scope:** `trade:read_write` [Try in API console](https://test.deribit.com/api_console?method=%2Fprivate%2Fedit_by_label)",
  "deprecated": false,
  "params": {
   "label": {
    "type": "string",
    "description": "user defined label for the order (maximum 64 characters)"
   },
   "instrument_name": {
    "type": "string",
    "description": "Instrument name"
   },
   "amount": {
    "type": "number",
    "description": "It represents the requested order size. For perpetual and inverse futures the amount is in USD units. For options and linear futures it is the underlying base currency coin. The `amount` is a mandatory parameter if `contracts` parameter is missing. If both `contracts` and `amount` parameter are passed they must match each other otherwise error is returned."
   },
   "contracts": {
    "type": "number",
    "description": "It represents the requested order size in contract units and can be passed instead of `amount`. The `contracts` is a mandatory parameter if `amount` parameter is missing. If both `contracts` and `amount` parameter are passed they must match each other otherwise error is returned."
   },
   "price": {
    "type": "number",
    "description": "The order price in base currency. When editing an option order with advanced=usd, the field price should be the option price value in USD. When editing an option order with advanced=implv, the field price should be a value of implied volatility in percentages. For example, price=100, means implied volatility of 100%"
   },
   "post_only": {
    "type": "boolean",
    "description": "If true, the order is considered post-only. If the new price would cause the order to be filled immediately (as taker), the price will be changed to be just below or above the spread (accordingly to the original order type). Only valid in combination with time_in_force=`\"good_til_cancelled\"` For spot trading routed to Coinbase Exchange, the price is never adjusted: `\"post_only\"` must be combined with `\"reject_post_only\"` set to true, and the order is rejected if it would be matched instantly."
   },
   "reduce_only": {
    "type": "boolean",
    "description": "If `true`, the order is considered reduce-only which is intended to only reduce a current position"
   },
   "reject_post_only": {
    "type": "boolean",
    "description": "If an order is considered post-only and this field is set to true then the order is put to the order book unmodified or the request is rejected. Only valid in combination with `\"post_only\"` set to true For spot trading routed to Coinbase Exchange, this must be set to true whenever `\"post_only\"` is true; otherwise the request is rejected with `post_only_not_allowed`."
   },
   "advanced": {
    "type": "string",
    "enum": [
     "usd",
     "implv"
    ],
    "description": "Advanced option order type. If you have posted an advanced option order, it is necessary to re-supply this parameter when editing it (Only for options)"
   },
   "trigger_price": {
    "type": "number",
    "description": "Trigger price, required for trigger orders only (Stop-loss or Take-profit orders)"
   },
   "mmp": {
    "type": "boolean",
    "description": "Order MMP flag, only for order_type 'limit'"
   },
   "valid_until": {
    "type": "integer",
    "description": "Timestamp, when provided server will start processing request in Matching Engine only before given timestamp, in other cases `timed_out` error will be responded. Remember that the given timestamp should be consistent with the server's time, use /public/time method to obtain current server time."
   }
  },
  "required": [
   "instrument_name"
  ]
 },
