 "private/get_settlement_history_by_currency": {
  "scope": "private",
  "tags": [
   "Trading",
   "Private"
  ],
  "summary": "Retrieves settlement, delivery, and bankruptcy events that have affected your account for a specific currency.",
  "description": "Retrieves settlement, delivery, and bankruptcy events that have affected your account for a specific currency. **Settlement vs. delivery:** Settlement is a daily event (at 08:00 UTC) for futures and perpetual positions that converts unrealized profit and loss into realized profit and loss. Option positions do not settle. Delivery is a one-time event that occurs when a futures or options contract expires — any remaining open position is closed at the delivery price. Delivery does not apply to perpetual or spot instruments. Both events take place at 08:00 UTC, which is why they are sometimes conflated. Results can be filtered by settlement type and timestamp. Use pagination parameters (`count` and `continuation`) to retrieve large settlement histories. This data is useful for tracking account-affecting settlement events and understanding how contract expirations impact your account. **Scope:** `trade:read` [Try in API console](https://test.deribit.com/api_console?method=%2Fprivate%2Fget_settlement_history_by_currency)",
  "deprecated": false,
  "params": {
   "currency": {
    "type": "string",
    "enum": [
     "BTC",
     "ETH",
     "USDC",
     "USDT",
     "EURR"
    ],
    "description": "The currency symbol. **📖 Related Article:** [Using the currency Parameter](https://docs.deribit.com/articles/currency-parameter)"
   },
   "type": {
    "type": "string",
    "enum": [
     "settlement",
     "delivery",
     "bankruptcy"
    ],
    "description": "Settlement type"
   },
   "count": {
    "type": "integer",
    "description": "Number of requested items, default - `20`, maximum - `1000`"
   },
   "continuation": {
    "type": "string",
    "description": "Continuation token for pagination"
   },
   "search_start_timestamp": {
    "type": "integer",
    "description": "The latest timestamp to return result from (milliseconds since the UNIX epoch)"
   }
  },
  "required": [
   "currency"
  ]
 },
